<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch , useId} from 'vue'
import { useAuthStore } from '../stores/auth'
import { useWorkspaceStore } from '../stores/workspace'
import { useI18n } from '../i18n'
import type { BillingCycle, IncomePeriodPreview, IncomeSplit } from '../api/types'
import { amountStep, majorToMinor, minorToInput } from '../api/money'
import { todayInput, fromDateInput, fromDateTimeInput } from '../dateInput'
import EmptyState from './EmptyState.vue'
import MoneyValue from './MoneyValue.vue'
import SyncBadge from './SyncBadge.vue'
import CategorySelect from './CategorySelect.vue'

const a11yId = useId()

const props=defineProps<{personal:boolean;groupId?:string;canWrite:boolean;pendingOnly?:boolean}>()
const workspace=useWorkspaceStore(),auth=useAuthStore(),{tr,formatDate}=useI18n()
const busy=ref(false),error=ref(''),selectedId=ref(''),occurrenceBusy=ref(false),skipReason=ref('')
const actualAmounts=reactive<Record<string,string>>({})
const viewerTimezone=computed(()=>workspace.currentGroup?.timezone||auth.record?.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC')
const members=computed(()=>workspace.members.filter(member=>!(member.user?.placeholder&&member.user?.linkedUserId)))
const today=()=>todayInput(viewerTimezone.value)
const backfillThrough=ref(today()),backfillPreview=ref<IncomePeriodPreview>(),backfillBusy=ref(false)
const form=reactive({title:'',categoryId:'',amount:'',currency:'TWD',cycle:'monthly' as BillingCycle,interval:'1',startsOn:today(),endsOn:'',postingMode:'automatic' as 'automatic'|'manual'})
watch(()=>form.cycle,(cycle)=>{if(cycle==='every_n_hours'&&!form.startsOn.includes('T'))form.startsOn=`${today()}T09:00`;else if(cycle!=='every_n_hours'&&form.startsOn.includes('T'))form.startsOn=form.startsOn.slice(0,10)})
const active= computed(()=>workspace.recurringIncomes.filter(item=>!item.pendingSync))
const selected=computed(()=>active.value.find(item=>item.id===selectedId.value))
const pending=computed(()=>workspace.incomeOccurrences.filter(item=>item.status==='pending'||item.status==='failed'))
const visibleOccurrences=computed(()=>props.pendingOnly?pending.value:selected.value?workspace.incomeOccurrences.filter(item=>item.recurringIncomeId===selected.value?.id):[])
function formatLocal(value:string){return formatDate(value,{dateStyle:'medium',timeZone:viewerTimezone.value})}
async function load(){error.value='';try{await Promise.all([workspace.loadCategories(props.personal?'personal':'group',props.groupId||workspace.currentGroupId,'income'),workspace.loadRecurringIncomes(props.personal?'personal':'group')]);const pages=await Promise.all(workspace.recurringIncomes.map(item=>workspace.loadIncomeOccurrences(item.id,item.groupId||'')));workspace.incomeOccurrences=pages.flat();for(const item of workspace.incomeOccurrences)if(actualAmounts[item.id]===undefined)actualAmounts[item.id]=minorToInput(item.template.amountMinor,item.template.currency)}catch{error.value=workspace.localizedError||tr('requestFailed')}}
watch(()=>[props.groupId,props.personal],()=>{selectedId.value='';void load()})
onMounted(()=>void load())
async function addCategory(name:string,icon='tag'){try{const value=await workspace.createCategory(props.personal?'personal':'group',name,props.groupId||workspace.currentGroupId,icon,'income');form.categoryId=value.id}catch{error.value=workspace.localizedError||tr('requestFailed')}}
async function create(){if(busy.value||!props.canWrite||!form.title.trim()||!form.amount.trim())return;busy.value=true;error.value='';try{const groupId=props.personal?'':props.groupId||workspace.currentGroupId;const earnedBy=auth.record?.id||'';const amountMinor=majorToMinor(form.amount,form.currency);const splits:IncomeSplit[]=props.personal?[]:members.value.map(member=>({userId:member.userId,amountMinor:0}));const startsOn=form.cycle==='every_n_hours'?fromDateTimeInput(form.startsOn,viewerTimezone.value):fromDateInput(form.startsOn,viewerTimezone.value);const now=new Date().toISOString();const category=workspace.categories.find(item=>item.id===form.categoryId);const input={groupId:groupId||undefined,ownerId:props.personal?auth.record?.id:undefined,template:{title:form.title.trim(),category:category?.customName||category?.systemKey||'',categoryId:form.categoryId||undefined,amountMinor,currency:form.currency,baseCurrency:form.currency,baseAmountMinor:amountMinor,exchangeRate:'1',exchangeRateDate:now,rateMode:'automatic' as const,earnedBy,receivedOn:startsOn,notes:'',splitMode:'equal' as const,splits:props.personal?undefined:splits},timezone:viewerTimezone.value,cycle:form.cycle,interval:Number(form.interval),startsOn,nextOn:startsOn,endsOn:form.endsOn?fromDateInput(form.endsOn,viewerTimezone.value):undefined,postingMode:form.postingMode,status:'active' as const};const ok=await workspace.createRecurringIncome(input,groupId);if(!ok)throw new Error(workspace.localizedError||tr('requestFailed'));Object.assign(form,{title:'',categoryId:'',amount:'',startsOn:form.cycle==='every_n_hours'?`${today()}T09:00`:today(),endsOn:''});await load()}catch(reason){error.value=reason instanceof Error?reason.message:tr('requestFailed')}finally{busy.value=false}}
async function changeStatus(id:string,status:'active'|'paused'|'ended'){if(!workspace.online){error.value=tr('offlineActionDisabled');return};const ok=await workspace.setRecurringIncomeStatus(id,status,props.groupId||'');if(!ok)error.value=workspace.localizedError||tr('requestFailed');else await load()}
async function confirm(item:(typeof pending.value)[number]){occurrenceBusy.value=true;const template=item.template;const actual={...template,amountMinor:majorToMinor(actualAmounts[item.id]||minorToInput(template.amountMinor,template.currency),template.currency),receivedOn:item.scheduledOn};const ok=await workspace.confirmIncomeOccurrence(item.recurringIncomeId,item.scheduledOn,actual,props.groupId||'');if(!ok)error.value=workspace.localizedError||tr('requestFailed');await load();occurrenceBusy.value=false}
function cycleLabel(cycle:BillingCycle){return ({daily:tr('daily'),every_n_days:tr('everyNDays'),weekly:tr('weekly'),every_n_weeks:tr('everyNWeeks'),every_n_hours:tr('everyNHours'),monthly:tr('monthly'),quarterly:tr('quarterly'),yearly:tr('yearly')} as Record<BillingCycle,string>)[cycle]}
async function skip(item:(typeof pending.value)[number]){if(!selected.value||!skipReason.value.trim())return;occurrenceBusy.value=true;const ok=await workspace.skipIncomeOccurrence(item.recurringIncomeId,item.scheduledOn,skipReason.value,props.groupId||'');if(!ok)error.value=workspace.localizedError||tr('requestFailed');skipReason.value='';await load();occurrenceBusy.value=false}
async function retry(item:(typeof pending.value)[number]){if(!workspace.online){error.value=tr('offlineActionDisabled');return};const ok=await workspace.retryIncomeOccurrence(item.recurringIncomeId,item.scheduledOn,props.groupId||'');if(!ok)error.value=workspace.localizedError||tr('requestFailed');await load()}
async function previewBackfill(){if(!selected.value||!workspace.online)return;backfillBusy.value=true;error.value='';backfillPreview.value=await workspace.previewRecurringIncomeBackfill(selected.value.id,fromDateInput(backfillThrough.value,viewerTimezone.value),props.groupId||'');if(!backfillPreview.value)error.value=workspace.error||tr('requestFailed');backfillBusy.value=false}
async function executeBackfill(){if(!selected.value||!backfillPreview.value||!workspace.online)return;backfillBusy.value=true;const ok=await workspace.backfillRecurringIncome(selected.value.id,fromDateInput(backfillThrough.value,viewerTimezone.value),props.groupId||'');if(!ok)error.value=workspace.localizedError||tr('requestFailed');else{backfillPreview.value=undefined;await load()}backfillBusy.value=false}
</script>

<template><div class="recurring-income-panel"><p v-if="error" class="notice danger" role="alert">{{error}}</p>
  <section v-if="canWrite" class="card recurring-create"><div class="card-title"><div><h2>{{tr('createRecurringIncome')}}</h2><p class="field-help">{{tr('recurringIncomeDescription')}}</p></div><span class="status-text">{{tr('recurringIncomeOnlyPostsWhenReceived')}}</span></div>
    <form class="recurring-form" @submit.prevent="create"><label>{{tr('item')}}<input v-model="form.title" required maxlength="160"></label><label :for="a11yId + '-field-1'">{{tr('category')}}<CategorySelect v-model="form.categoryId" :categories="workspace.categories" @create="addCategory" :id="a11yId + '-field-1'"/></label><label>{{tr('amount')}}<input v-model="form.amount" type="number" min="0" :step="amountStep(form.currency)" required></label><label>{{tr('currency')}}<select v-model="form.currency"><option v-for="currency in workspace.currencies" :key="currency.code" :value="currency.code">{{currency.code}}</option></select></label><label>{{tr('cycle')}}<select v-model="form.cycle"><option v-for="cycle in (['daily','every_n_days','weekly','every_n_weeks','every_n_hours','monthly','quarterly','yearly'] as BillingCycle[])" :key="cycle" :value="cycle">{{cycleLabel(cycle)}}</option></select></label><label>{{tr('billingInterval')}}<input v-model="form.interval" type="number" min="1" max="600" required></label><label>{{tr('firstBilling')}}<input v-model="form.startsOn" :type="form.cycle==='every_n_hours'?'datetime-local':'date'" required></label><label>{{tr('endDate')}}<input v-model="form.endsOn" type="date"></label><label>{{tr('postingMode')}}<select v-model="form.postingMode"><option value="automatic">{{tr('automaticPosting')}}</option><option value="manual">{{tr('manualConfirmation')}}</option></select></label><button class="primary" :disabled="busy||!workspace.online" :title="workspace.online?'':tr('offlineActionDisabled')" type="submit">{{tr('createRecurringIncome')}}</button></form>
  </section>
  <section class="card"><div class="card-title"><h2>{{tr('recurringIncome')}}</h2><span>{{tr('records',{count:active.length})}}</span></div><div v-if="active.length" class="data-list"><article v-for="item in active" :key="item.id" class="data-row recurring-row"><button class="recurring-main" @click="selectedId=selectedId===item.id?'':item.id;selectedId&&workspace.loadIncomeOccurrences(item.id,item.groupId||'')" type="button"><strong>{{item.template.title}}</strong><small>{{cycleLabel(item.cycle)}} · {{tr(item.postingMode==='manual'?'manualConfirmation':'automaticPosting')}}</small><span>{{tr('nextReceipt')}}: {{formatLocal(item.nextOn)}} · {{tr(item.status)}}</span><SyncBadge :pending-sync="item.pendingSync" :sync-error="item.syncError"/></button><div v-if="canWrite" class="inline-actions"><button v-if="item.status==='active'" class="ghost" :disabled="!workspace.online" @click="changeStatus(item.id,'paused')" type="button">{{tr('pause')}}</button><button v-else-if="item.status==='paused'" class="ghost" :disabled="!workspace.online" @click="changeStatus(item.id,'active')" type="button">{{tr('resume')}}</button></div></article></div><EmptyState v-else :title="tr('noRecurringIncome')" :description="tr('createRecurringIncome')"/></section>
  <section v-if="selected&&canWrite" class="card backfill-card"><div class="card-title"><div><h2>{{tr('incomeBackfill')}}</h2><p class="field-help">{{tr('incomeBackfillDescription')}}</p></div><strong>{{selected.template.title}}</strong></div><div class="backfill-actions"><label>{{tr('backfillThrough')}}<input v-model="backfillThrough" type="date"></label><button class="ghost" :disabled="!workspace.online||backfillBusy" @click="previewBackfill" type="button">{{tr('previewBackfill')}}</button><button v-if="backfillPreview" class="primary" :disabled="!workspace.online||backfillBusy||!backfillPreview.total" @click="executeBackfill" type="button">{{tr('applyBackfill')}}</button></div><div v-if="backfillPreview" class="notice inline"><strong>{{tr('backfillPeriods',{count:backfillPreview.total})}}</strong><span v-for="period in backfillPreview.periods.slice(0,5)" :key="period.scheduledOn">{{formatLocal(period.scheduledOn)}} · {{tr(period.status)}} · {{minorToInput(period.template.amountMinor,period.template.currency)}} {{period.template.currency}}</span></div></section>
  <section v-if="selected||pendingOnly" class="card"><div class="card-title"><h2>{{pendingOnly?tr('pendingIncome'):tr('incomePeriods')}}</h2><span>{{selected?.template.title||tr('incomePeriods')}}</span></div><div v-if="visibleOccurrences.length" class="data-list"><article v-for="item in visibleOccurrences" :key="item.id" class="data-row occurrence-row"><div class="grow"><strong>{{formatLocal(item.scheduledOn)}}</strong><small>{{tr(item.status)}} <template v-if="item.reason">· {{item.reason}}</template></small><small>{{item.template.title}}</small></div><label v-if="item.status==='pending'&&item.postingMode==='manual'">{{tr('actualAmount')}}<input v-model="actualAmounts[item.id]" type="number" min="0" :step="amountStep(item.template.currency)"></label><MoneyValue :amount="item.template.amountMinor" :currency="item.template.currency"/><div v-if="canWrite&&item.status==='pending'" class="inline-actions"><button class="primary" :disabled="occurrenceBusy||!workspace.online" @click="confirm(item)" type="button">{{tr('confirmReceived')}}</button><input v-model="skipReason" :aria-label="tr('skipReason')" :placeholder="tr('skipReason')"><button class="ghost" :disabled="occurrenceBusy||!skipReason.trim()||!workspace.online" @click="skip(item)" type="button">{{tr('skipOccurrence')}}</button></div><button v-if="canWrite&&item.status==='failed'" class="ghost" :disabled="!workspace.online" @click="retry(item)" type="button">{{tr('retry')}}</button></article></div><EmptyState v-else :title="tr('noIncomePeriods')" :description="tr('incomePeriods')"/></section>
</div></template>
<style scoped>.recurring-income-panel{display:grid;gap:16px}.recurring-form{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.recurring-form label{display:grid;gap:6px;color:var(--ink);font-size:13px;font-weight:700}.recurring-form input,.recurring-form select,.occurrence-row input{min-width:0;width:100%;padding:10px;border:1px solid var(--line);border-radius:9px;background:var(--surface);color:var(--ink)}.recurring-form button{align-self:end}.recurring-main{display:grid;gap:4px;flex:1;text-align:left;background:transparent;border:0;color:var(--ink);cursor:pointer}.recurring-main small,.recurring-main span{color:var(--muted)}.recurring-row,.occurrence-row{display:flex;align-items:center;gap:12px}.occurrence-row .inline-actions{display:flex;gap:8px;align-items:center}.status-text{color:var(--muted);font-size:12px}@media(max-width:760px){.recurring-form{grid-template-columns:repeat(2,minmax(0,1fr))}.recurring-row,.occurrence-row{align-items:flex-start;flex-wrap:wrap}.occurrence-row .inline-actions{width:100%;flex-wrap:wrap}.occurrence-row .inline-actions input{flex:1;min-width:120px}}@media(max-width:420px){.recurring-form{grid-template-columns:1fr}}</style>
